                preference.append((cost, j + 1))  # 1-indexed

            # Sort by cost ascending
            preference.sort()
            prefs.append(preference)

        # Gale-Shapley style: each "free" city proposes to preferred cities
        free = list(range(n + 1))  # 1-indexed, free[i] = city, -1 if matched

