        cards.append((a, b))

    def is_balanced(seq):
        bal = 0
        for x in seq:
            bal += x
            if bal < 0:
                return False
        return bal == 0

    # Sort by front value to try a greedy approach
    cards_sorted = sorted(cards, key=lambda x: x[0])

    if is_balanced([c[0] for c in cards_sorted]) and is_balanced([c[1] for c in cards_sorted]):
        result = ['YES']
        result.append('\n')
        for a, b in cards_sorted:
            result.append(f'{a} {b}')
