    for i in range(m):
        x, y, w = map(int, lines[2 + i].split())
        edges.append((x, y, w, i + 1))  # Store 0-indexed internally, 1-indexed output

    # Build adjacency list with edge indices
    adj = [[] for _ in range(n + 1)]
    for x, y, w, idx in edges:
        adj[x].append((y, idx))
        adj[y].append((x, idx))

    def bfs(start, blocked):
        """BFS from start node, avoiding blocked edges"""
        visited = {start}
        queue = [start]
        head = 0
        while head < len(queue):
            u = queue[head]
            head += 1
            for v, e_idx in adj[u]:
                if e_idx not in blocked and v not in visited:
                    visited.add(v)
                    queue.append(v)
        return visited

    # Check if s and t are already disconnected
    visited = bfs(s, set())
    if t not in visited:
        return "0\n0"

    # Find all edges that lie on some s-t path
    # An edge (u, v) is on some s-t path if s can reach u AND v can reach t
    forward = bfs(s, set())
    backward = bfs(t, set())

    edges_on_path = []
    for idx, (u, v, w, orig_idx) in enumerate(edges):
        if u != v:  # Skip self-loops
            # Edge (u,v) is on path if s can reach u and v can reach t (with backward BFS from t)
            # Actually need to check both directions - edge is critical if it's the only way
            if forward[u]:
                edges_on_path.append((idx, u, v, w, orig_idx))

    # Check single edge removal (crucial edges)
    min_cost = float('inf')
    best_single = []

    for idx, u, v, w, orig_idx in edges:
        if u == v:  # Skip self-loops
            continue
        blocked = {idx}
        if t not in bfs(s, blocked):  # If blocking disconnects s from t
            if w < min_cost:
                min_cost = w
                best_single = [orig_idx]

    # Check two edge removal
    min_cost_pair = float('inf')
    best_pair = []

    for i in range(len(edges)):
        idx1, u1, v1, w1, orig1 = edges[i]
        for j in range(i + 1, len(edges)):
            idx2, u2, v2, w2, orig2 = edges[j]
            if u1 == v1 or u2 == v2:
                continue
            blocked = {idx1, idx2}
            if t not in bfs(s, blocked):  # If blocking both disconnects s from t
