    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for line in lines[1:]:
        if line.strip():
            u, v = map(int, line.split())
            adj[u].append(v)
            adj[v].append(u)

    threshold = int((n ** 0.5) + 0.99999999999999999999)
    if threshold < 1:
        threshold = 1

    # DFS to find a cycle
    visited = [False] * (n + 1)
    parent = [-1] * (n + 1)
    depth = [0] * (n + 1)

    def dfs(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                parent[v] = u
                depth[v] = depth[u] + 1
                cycle = dfs(v)
                if cycle:
                    return cycle
            elif v != parent[u]:
                # Found a back-edge (u, v)
                # Cycle consists of path from v to u via parent pointers + edge (u, v)
                cycle = []
                curr = u
                while curr != v:
                    cycle.append(curr)
                    curr = parent[curr]
                cycle.append(v)
                cycle.append(u)

                if len(cycle) >= threshold:
                    return cycle

        return None

    cycle = dfs(1)

    if cycle and len(cycle) >= threshold:
        return "2\n" + str(len(cycle)) + "\n" + " ".join(map(str, cycle)) + "\n"

    # Fall back to independent set
    degrees = [len(adj[v]) for v in range(n + 1)]
    indep_set = []
    removed = [False] * (n + 1)

    for v in range(1, n + 1):
        if removed[v]:
            continue
        if len(indep_set) >= threshold:
            break

        indep_set.append(v)
        for u in adj[v]:
            if removed[u] == -1:
                removed[u] = True

    # Remove the nodes in indep_set and their neighbors
    indep_set_final = []

    while len(indep_set_final) < threshold:
        v = None
        min_degree = float('inf')

        for u in range(1, n + 1):
            if not removed[u] or removed[u] == -1:
                if u not in indep_set_final:
                    deg = len(adj[u])
                    for w in adj[u]:
                        if removed[w] is False:
                            deg -= 1
                    if deg < min_degree:
                        min_degree = deg
                        v = u

        if v is None:
            break

        indep_set_final.append(v)
        for u in adj[v]:
            removed[u] = True

