        # Second pass: check consistency for targets (reverse mapping)
        reverse = {}
        for j in range(m):
            s_char = S[i + j]
            t_char = T[j]

            if t_char in reverse:
                if reverse[t_char] != s_char:
                    valid = False
                    break
            else:
                reverse[t_char] = s_char

        if valid:
            result.append(i + 1)  # 1-indexed positions

    result.sort()
    return f"{len(result)}\n" + " ".join(map(str, result))

