    # Parse input
    lines = grid_str.strip().split('\n')
    n = int(lines[0])
    matrix = []
    for i in range(1, n + 1):
        matrix.append(list(map(int, lines[i].split())))

    # Count factors of 2 and 5 for each number
    def count_factors(num):
        if num == 0:
            return 0, 0
        c2, c5 = 0, 0
        while num % 2 == 0:
            c2 += 1
            num //= 2
        while num % 5 == 0:
            c5 += 1
            num //= 5
        return c2, c5

    # Build factor table
    f2 = [[0] * n for _ in range(n)]
    f5 = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            f2[i][j], f5[i][j] = count_factors(matrix[i][j])

    # DP: for each cell store list of (c2, c5) reaching Pareto optimality
    dp = [[[] for _ in range(n)] for _ in range(n)]
    dp[0][0].append((f2[0][0], f5[0][0]))

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            states = []
            if i > 0:
                for c2, c5 in dp[i-1][j]:
                    states.append((c2 + f2[i][j], c5 + f5[i][j]))
            if j > 0:
                for c2, c5 in dp[i][j-1]:
                    states.append((c2 + f2[i][j], c5 + f5[i][j]))
            # Pareto pruning: keep only non-dominated pairs
            pruned = []
            best_idx = -1
            for idx, (c2, c5) in enumerate(states):
                if best_idx >= 0:
                    is_dom = c2 <= pruned[best_idx][0] and c5 <= pruned[best_idx][1]
                    if not is_dom:
                        best_idx = -1
                if best_idx < 0:
                    pruned.append(states[idx])
                    best_idx = len(pruned) - 1
            dp[i][j] = pruned

    # Find result at bottom-right
    final = dp[n-1][n-1] if dp[n-1][n-1] else dp[0][0]
    min_zeros = min(min(c2, c5) for c2, c5 in final)

    # Reconstruct path
    path = ""
    i, j = n - 1, n - 1
    trans = [(f2[i][j], f5[i][j], 'U', (i-1, j)) if i > 0 else None]
    if j > 0:
        trans.append((f2[i][j], f5[i][j], 'L', (i, j-1)))
    for _ in range((2 * n - 2) - 1, 0, -1):
        curr = trans.pop()
        path += curr[2]

    path = path[::-1]
    return f"{min_zeros}\n{path}"

