    n, r = map(int, input_str.split()[:2])

    # Generate all candidate integer points within distance r from origin
    candidates = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x * x + y * y <= r * r:
                candidates.append((x, y))

    candidates = sorted(list(set(candidates)), key=lambda p: p[0]*p[0] + p[1]*p[1], reverse=True)

    best_score = -1
    best_assignment = None

    def calc_score(assignment):
        xs = [p[0] for p in assignment]
        ys = [p[1] for p in assignment]
        sum_sq = sum(x*x + y*y for x, y in assignment)
        return n * sum_sq - sum(xs)**2 - sum(ys)**2

    # Store best assignments by score
    best_assignments = {}

    def search(remaining, start_idx, current, s_x, s_y, s_sq):
        if len(current) == n:
            score = calc_score(current)
            if score not in best_assignments:
                best_assignments[score] = current
            elif score > best_assignments[score][0]:
                best_assignments[score] = current
            return

        if remaining == 0:
            return

        for i in range(start_idx, len(candidates)):
            x, y = candidates[i]
            current.append((x, y))
            new_s_x = s_x + x
            new_s_y = s_y + y
            new_s_sq = s_sq + x*x + y*y
            search(remaining - 1, i, current, new_s_x, new_s_y, new_s_sq)
            current.pop()

    # For smaller n, use combinations with replacement
    for combo in combinations_with_replacement(range(len(candidates)), n):
        assignment = [candidates[i] for i in combo]
        score = calc_score(assignment)
        if score not in best_assignments or score > best_assignments[score][0]:
            best_assignments[score] = assignment

    best_score = max(best_assignments.keys())
    best_assignment = best_assignments[best_score]

    result = [str(best_score)]
    for x, y in best_assignment:
        result.append(f"{x} {y}")

    return '\n'.join(result)

