                for i in range(n):
                    for j in range(n):
                        new_matrix[i][j] = matrix[i][(j + 1) % n]
            elif op == 'D':
                # Cyclic shift rows down: a_{i,j} comes from a_{(i-1)%n,j}
                for i in range(n):
                    for j in range(n):
                        new_matrix[i][j] = matrix[(i - 1) % n][j]
            elif op == 'U':
