def solution(input_str):
    """
    Solves the geometric point pairing problem.
    Returns maximum moves and which points to pair.
    """
    lines = input_str.strip().split('\n')
    if len(lines) < 1 or not lines:
        return ""

    n = int(lines[0])
    if n == 0 or n < 1:
        return "0"

    points = []
    for i in range(1, n + 1):
        if i >= len(lines):
            break
        parts = lines[i].split()
        if len(parts) >= 4:
            a, b, c, d = int(parts[0]), int(parts[1]), int(parts[2]), int(parts[3])
            points.append((a, b, c, d))

    result_moves = []
    used = [False] * n

    def can_pair(p1, p2):
        """Check if two points can be moved to be collinear with (0,0)"""
        a, b, c, d = p1
        e, f, g, h = p2

        for x1 it in [(a + 1, b, c, d), (a, b, c + 1, d)]:
            for x2 it in [(e + 1, f, g, h), (e, f, g + 1, h)]:
                xa, db, xc, yc = x1 it
                if xa == 0 or xc == 0:
                    continue
                cross = xa * yc - xc * xa
                if cross == 0:
                    return True
        return False

    for i in range(n):
        if used[i]:
            continue
        for j in range(i + 1, n):
            if used[j]:
                continue

            if can_pair(points[i], points[j]):
                result_moves.append(f"{i + 1} {j + 1}")
                used[i] = True
                used[j] = True
                break

    output_lines = [str(len(result_moves))]
    for move in result_moves:
        output_lines.append(move)

    return '\n'.join(output_lines)

